from datetime import UTC, datetime
from email.utils import parsedate_to_datetime


def retry_after_seconds(response) -> int:
    raw = response.headers.get("Retry-After")
    if raw is None:
        return _FALLBACK_SECONDS
    try:
        return int(raw)
    except ValueError:
        pass
    try:
        retry_at = parsedate_to_datetime(raw)
    except (TypeError, ValueError):
        return _FALLBACK_SECONDS
    return max(0, int((retry_at - datetime.now(UTC)).total_seconds()))


# measured: upstream buckets its rate limiter on a 60s window, so a shorter retry re-hits the closed bucket
_FALLBACK_SECONDS = 60
